SELECT PersonId, ATC, COUNT(*) AS n, MAX(StartAt) AS LastDate, MAX(TreatId) AS MaxTreatId FROM dbo.OngoingTreatment ot WHERE ATC IN ('J01XX04','M04AC01','N05CM02' )GROUP BY PersonId, ATC UNION SELECT PersonId, SUBSTRING(ATC,1,5) AS ATCFragment, COUNT(*) AS n, MAX(StartAt) AS LastDate, MAX(TreatId) AS MaxTreatId FROM dbo.OngoingTreatment ot WHERE SUBSTRING(ATC,1,5) IN ('A10BA','B01AE','B01AF','B03BA','B03BB','G04BD','M04AA','M04AB','N02AA','N02AB','N02AE','N02AG','N02AJ','N02AX','N02BA','N05BA','N05BB','N05CD','N05CF','N05CH','N06DA','N06DX','R03AC','R03AK','R03BB','R03DA','R06AD','R06AE','R06AX' )GROUP BY PersonId, SUBSTRING(ATC,1,5) UNION SELECT PersonId, SUBSTRING(ATC,1,4) AS ATCFragment, COUNT(*) AS n, MAX(StartAt) AS LastDate, MAX(TreatId) AS MaxTreatId FROM dbo.OngoingTreatment ot WHERE SUBSTRING(ATC,1,4) IN ('A02A','A02B','A06A','A10A','A10B','B01A','B01C','B03A','C01A','G04C','H03A','M01A','N03A','N05A','N06A','N06D','S01E' )GROUP BY PersonId, SUBSTRING(ATC,1,4) UNION SELECT PersonId, SUBSTRING(ATC,1,3) AS ATCFragment, COUNT(*) AS n, MAX(StartAt) AS LastDate, MAX(TreatId) AS MaxTreatId FROM dbo.OngoingTreatment ot WHERE SUBSTRING(ATC,1,3) IN ('A11','C02','C03','C07','C08','C09','H02','N04' )GROUP BY PersonId, SUBSTRING(ATC,1,3) ORDER BY PersonId